import fs from 'node:fs'; import os from 'node:os'; import path from 'node:path';
import { withApp, pageHelpers, report } from '/Users/matiasrodriguezc/harness-runs/p08-wt-func/scripts/e2e/app-session.mjs';
const root = '/Users/matiasrodriguezc/harness-runs/p08-wt-func';
const dataDir = fs.mkdtempSync(path.join(os.tmpdir(), 'vf-data-'));
const outDir = fs.mkdtempSync(path.join(os.tmpdir(), 'vf-out-'));
const outFile = path.join(outDir, 'exported ñ conversation.md');
const docsDir = path.join(root, 'data/sample-documents');
const docs = fs.readdirSync(docsDir).map(f => path.join(docsDir, f));
const kb = 'window.knowledgeBase';
const C = []; const ck = (l, ok, d) => C.push([l, !!ok, d]);
const sleep = ms => new Promise(r => setTimeout(r, ms));

function structure(md, hist, label) {
  const heads = md.match(/^## Question \d+$/gm) ?? [];
  ck(`${label}: headings 1..${hist.length}`, JSON.stringify(heads) === JSON.stringify(hist.map((_, i) => `## Question ${i+1}`)), heads);
  const probs = [];
  hist.forEach((h, i) => {
    const hs = md.indexOf(`## Question ${i+1}\n`); const he = i+1 < hist.length ? md.indexOf(`## Question ${i+2}\n`) : md.length;
    const sec = md.slice(hs, he);
    const qp = sec.indexOf(h.question); if (qp < 0) { probs.push(`q${i+1} text`); return; }
    // question must directly follow heading
    if (!sec.slice(`## Question ${i+1}`.length).trimStart().startsWith(h.question)) probs.push(`q${i+1} not right after heading`);
    let pos = sec.indexOf(h.response.answer, qp + h.question.length); if (pos < 0) { probs.push(`a${i+1}`); return; }
    pos += h.response.answer.length;
    if (h.response.citations.length === 0) { if (sec.indexOf('No citations.', pos) < 0) probs.push(`q${i+1} No citations.`); }
    for (const c of h.response.citations) {
      const t = sec.indexOf(c.documentTitle, pos); if (t < 0) { probs.push(`q${i+1} title ${c.documentTitle}`); continue; } pos = t;
      for (const line of c.excerpt.split(/\r?\n/)) { const l = sec.indexOf(`> ${line}`, pos); if (l < 0) probs.push(`q${i+1} excerpt line ${JSON.stringify(line)}`); else pos = l + 2 + line.length; }
    }
  });
  ck(`${label}: question/answer/citations per section in order`, probs.length === 0, probs.slice(0,5));
}
async function click(send, evaluate, sel) {
  const r = await evaluate(`(() => { const e = document.querySelector('${sel}'); e.scrollIntoView(); const b = e.getBoundingClientRect(); return {x: b.x + b.width/2, y: b.y + b.height/2}; })()`);
  for (const type of ['mousePressed', 'mouseReleased']) await send('Input.dispatchMouseEvent', { type, x: r.x, y: r.y, button: 'left', clickCount: 1 });
}
async function typeAsk(send, evaluate, q) {
  await evaluate(`document.querySelector('[aria-label="Ask a question"]').focus()`);
  await send('Input.insertText', { text: q });
  await send('Input.dispatchKeyEvent', { type: 'keyDown', key: 'Enter', code: 'Enter', windowsVirtualKeyCode: 13, text: '\r' });
  await send('Input.dispatchKeyEvent', { type: 'keyUp', key: 'Enter', code: 'Enter', windowsVirtualKeyCode: 13 });
}
const BTN = '[aria-label="Export conversation"]';
const msg = `(() => ({status: [...document.querySelectorAll('[role=status]')].map(e=>e.innerText), alert: [...document.querySelectorAll('[role=alert]')].map(e=>e.innerText)}))()`;
const questions = ['What is the architecture design?', 'How does retrieval work?', 'Who attended the meeting?'];
let saved = {};
try {
 // Session 1: save to real path
 await withApp({ dataDir, port: 9471, env: { KB_EXPORT_SAVE_PATH: outFile } }, async ({ evaluate, waitFor, send }) => {
  await evaluate(pageHelpers);
  const keys = await evaluate(`Object.keys(${kb}).join(',')`);
  ck('C1 export is function', await evaluate(`typeof ${kb}.conversation.export`) === 'function', keys);
  ck('C1 other namespaces present', ['documents','indexing','qa','feedback','app'].every(k => keys.split(',').includes(k)), keys);
  const e0 = await evaluate(`${kb}.conversation.export()`);
  ck('C2 fresh empty export', typeof e0 === 'string' && e0.includes('# Conversation export') && e0.includes('No questions yet.') && !e0.includes('## Question'), e0);
  const b0 = await evaluate(`(() => { const f = document.querySelector('[aria-label="Ask a question"]').closest('form'); const b=[...document.querySelectorAll('${BTN}')]; return b.map(x=>({tag:x.tagName,type:x.type,dis:x.disabled,inForm:f&&f.contains(x),vis:x.offsetParent!==null&&x.getBoundingClientRect().width>0})) })()`);
  ck('C7 button in form, non-submit, enabled, visible (empty)', b0.length===1 && b0[0].tag==='BUTTON' && b0[0].type!=='submit' && !b0[0].dis && b0[0].inForm && b0[0].vis, b0);
  // click export while empty -> file with empty doc
  await click(send, evaluate, BTN);
  await waitFor(`[...document.querySelectorAll('[role=status]')].some(e=>e.innerText.includes('Conversation exported'))`);
  const f0 = fs.readFileSync(outFile, 'utf8');
  ck('C8 empty conversation saved via click equals export()', f0 === e0, f0);
  ck('C9 status shows path', (await evaluate(msg)).status.some(s => s.includes(outFile)), await evaluate(msg));
  ck('C7 click did not create history', (await evaluate(`${kb}.qa.history()`)).length === 0);

  await evaluate(`(async () => { for (const d of ${JSON.stringify(docs)}) await ${kb}.documents.import(d); await ${kb}.indexing.start(); return true; })()`);
  await waitFor(`${kb}.app.status().then(s => s.indexStatus === 'ready')`, 20000).catch(()=>{});
  // ask via UI
  for (let i = 0; i < questions.length; i++) {
    await typeAsk(send, evaluate, questions[i]);
    await waitFor(`${kb}.qa.history().then(h => h.length === ${i+1})`, 15000);
    await sleep(300);
  }
  const h3 = await evaluate(`${kb}.qa.history()`);
  ck('C3 history has 3 asked questions in order', JSON.stringify(h3.map(h=>h.question)) === JSON.stringify(questions), h3.map(h=>h.question));
  ck('C3 at least one answer has citations', h3.some(h=>h.response.citations.length>0), h3.map(h=>h.response.citations.length));
  ck('C5 some excerpt is multi-line (coverage)', h3.some(h=>h.response.citations.some(c=>c.excerpt.includes('\n'))), null);
  const e3 = await evaluate(`${kb}.conversation.export()`);
  structure(e3, h3, 'C3-5 bridge');
  const e3b = await evaluate(`${kb}.conversation.export()`);
  ck('C6 export does not change history', JSON.stringify(await evaluate(`${kb}.qa.history()`)) === JSON.stringify(h3) && e3b === e3);
  // click export, check file == export()
  const b1 = await evaluate(`(() => { const b=document.querySelector('${BTN}'); return {dis:b.disabled, vis:b.offsetParent!==null}})()`);
  ck('C7 button enabled+visible (non-empty)', !b1.dis && b1.vis, b1);
  fs.rmSync(outFile);
  await click(send, evaluate, BTN);
  await waitFor(`fetch ? true : true`); await sleep(800);
  ck('C8 file written', fs.existsSync(outFile));
  const f3 = fs.existsSync(outFile) ? fs.readFileSync(outFile) : Buffer.alloc(0);
  ck('C8 file bytes === UTF-8 of export()', f3.equals(Buffer.from(e3, 'utf8')), f3.length + ' vs ' + Buffer.byteLength(e3));
  ck('C7 click did not ask a question', (await evaluate(`${kb}.qa.history()`)).length === 3);
  ck('C9 status with path', (await evaluate(msg)).status.some(s => s.includes(outFile)), await evaluate(msg));
  // ask 4th
  await typeAsk(send, evaluate, 'What are the next steps?');
  await waitFor(`${kb}.qa.history().then(h => h.length === 4)`, 15000);
  const h4 = await evaluate(`${kb}.qa.history()`); const e4 = await evaluate(`${kb}.conversation.export()`);
  ck('C6 4th question adds ## Question 4', e4.includes('## Question 4') && !e4.includes('## Question 5'));
  structure(e4, h4, 'C6 after 4th');
  saved = { h4, e4 };
