  ck('info: answers with no citations', true, h4.map(h=>h.response.citations.length));
 });
 // Session 2: restart same dataDir; cancel
 await withApp({ dataDir, port: 9472, env: { KB_EXPORT_SAVE_PATH: 'cancel' } }, async ({ evaluate, send }) => {
  await evaluate(pageHelpers);
  const e = await evaluate(`${kb}.conversation.export()`);
